import { describe, expect, it } from "vitest";
import { assemblyStats } from "./n50.js";

describe("assemblyStats", () => {
  it("computes stats for [100,200,300,400,500]", () => {
    const s = assemblyStats([100, 200, 300, 400, 500]);
    expect(s.totalLength).toBe(1500);
    expect(s.n50).toBe(400);
    expect(s.l50).toBe(2);
    expect(s.n90).toBe(200);
    expect(s.l90).toBe(4);
    expect(s.max).toBe(500);
    expect(s.mean).toBe(300);
  });

  it("handles a single contig", () => {
    const s = assemblyStats([7]);
    expect(s.totalLength).toBe(7);
    expect(s.n50).toBe(7);
    expect(s.l50).toBe(1);
    expect(s.n90).toBe(7);
    expect(s.l90).toBe(1);
    expect(s.max).toBe(7);
    expect(s.mean).toBe(7);
  });

  it("is order-independent", () => {
    expect(assemblyStats([500, 100, 400, 200, 300])).toEqual(
      assemblyStats([100, 200, 300, 400, 500]),
    );
  });

  it("throws on empty input", () => {
    expect(() => assemblyStats([])).toThrow();
  });
});

