export interface AssemblyStats {
  totalLength: number;
  n50: number;
  l50: number;
  n90: number;
  l90: number;
  max: number;
  mean: number;
}

/**
 * Compute assembly statistics for a list of contig lengths.
 *
 * Nx (e.g. N50, N90) is the length of the shortest contig in the smallest
 * set of longest contigs whose cumulative length is at least x% of the
 * total; Lx is that set's size.
 */
export function assemblyStats(lengths: number[]): AssemblyStats {
  if (!Array.isArray(lengths) || lengths.length === 0) {
    throw new Error("assemblyStats: input must be a non-empty array of lengths");
  }
  if (lengths.some((l) => !Number.isFinite(l) || l < 0)) {
    throw new Error("assemblyStats: lengths must be finite, non-negative numbers");
  }

  const sorted = [...lengths].sort((a, b) => b - a); // longest first
  const totalLength = sorted.reduce((sum, l) => sum + l, 0);

  const nx = (fraction: number): { nx: number; lx: number } => {
    const threshold = totalLength * fraction;
    let cumulative = 0;
    for (let i = 0; i < sorted.length; i++) {
      cumulative += sorted[i];
      if (cumulative >= threshold) {
        return { nx: sorted[i], lx: i + 1 };
      }
    }
    throw new Error("unreachable"); // threshold <= total always
  };

  const { nx: n50, lx: l50 } = nx(0.5);
  const { nx: n90, lx: l90 } = nx(0.9);

  return {
    totalLength,
    n50,
    l50,
    n90,
    l90,
    max: sorted[0],
    mean: totalLength / sorted.length,
  };
}

